from collections import deque
def solve(I):
    A=[row[:] for row in I]; H=len(A); W=len(A[0])
    sepv=set(); sepc=set()
    for r in range(H):
        if len(set(A[r]))==1 and A[r][0]!=0: sepv.add(r)
    for c in range(W):
        if len(set(A[r][c] for r in range(H)))==1 and A[0][c]!=0: sepc.add(c)
    out=[row[:] for row in A]
    seen=[[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if A[r][c]==0 or (r in sepv or c in sepc) or seen[r][c]: continue
            col=A[r][c]; comp=[]; q=deque([(r,c)]); seen[r][c]=True
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and not(seen[ny][nx] or (A[ny][nx]!=0 and (ny in sepv or nx in sepc)) or A[ny][nx]!=col):
                        continue
                    seen[ny][nx]=True; q.append((ny,nx))
            rs=[a for a,b in comp]; cs=[b for a,b in comp]
            rmin,rmax=min(rs),max(rs); cmin,cmax=min(cs),max(cs)
            cands=[]
            for s in sepc:
                if s<cmin-1 or s>cmax+1: continue
                tgt=[(y, 2*s-x) for y,x in comp if 0<=2*s-x<W]
                if any(x not in (0,) or out[y][x]!=0 or (y,x) in set(comp) for y,x in tgt): continue
                if not all(out[y][x]==0 for y,x in tgt-set(comp)): continue
                cands.append(tgt)
            for s in list(sepv):
                if s<rmin-1 or s>rmax+1: continue
                tgt=[(2*s-y,x) for y,x in comp if 0<=2*s-y<H]
                if any(out[y][x]!=0 or (y,x) in set(comp) for y,x in tgt): continue
                if not all(out[y][x]==0 for y,x in tgt-set(comp)): continue
                cands.append(tgt)
            if cands:
                for y,x in (set(map(tuple,cands[0])) - set(comp)): out[y][x]=col
    return out

